const listOrderableItems = `-- name: ListOrderableItems :many

SELECT i.id, i.restaurant_id, i.category_id, i.name, i.description, i.price_minor, i.is_available, i.sort_order, i.tags, i.allergens, i.calories, i.prep_minutes, i.created_at, i.updated_at, i.image_id, c.is_active AS category_is_active, m.id, m.restaurant_id, m.name, m.description, m.is_active, m.sort_order, m.available_from_min, m.available_to_min, m.days, m.created_at, m.updated_at
FROM items i
JOIN categories c ON c.id = i.category_id AND c.restaurant_id = i.restaurant_id
JOIN menus m ON m.id = c.menu_id AND m.restaurant_id = c.restaurant_id
WHERE i.restaurant_id = $1
  AND i.id = ANY($2::uuid[])
`

type ListOrderableItemsParams struct {
	RestaurantID uuid.UUID
	ItemIds      []uuid.UUID
}

type ListOrderableItemsRow struct {
	Item             Item
	CategoryIsActive bool
	Menu             Menu
}

// ------------------------------------------------------------------ catalog
//
// The order path reads the menu by id rather than reusing the public menu's
// whole-restaurant scans: a two-line cart should not pull a four-hundred-item
// menu through the connection to price it.
// Brings the category and menu along, because whether a dish can be ordered
// depends on both — a dish in a switched-off category, or on a menu outside its
// serving window, is not orderable no matter what the item row says.
func (q *Queries) ListOrderableItems(ctx context.Context, arg ListOrderableItemsParams) ([]ListOrderableItemsRow, error) {
	rows, err := q.db.Query(ctx, listOrderableItems, arg.RestaurantID, arg.ItemIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListOrderableItemsRow{}
	for rows.Next() {
		var i ListOrderableItemsRow
		if err := rows.Scan(
			&i.Item.ID,
			&i.Item.RestaurantID,
			&i.Item.CategoryID,
			&i.Item.Name,
			&i.Item.Description,
			&i.Item.PriceMinor,
			&i.Item.IsAvailable,
			&i.Item.SortOrder,
			&i.Item.Tags,
			&i.Item.Allergens,
			&i.Item.Calories,
			&i.Item.PrepMinutes,
			&i.Item.CreatedAt,
			&i.Item.UpdatedAt,
			&i.Item.ImageID,
			&i.CategoryIsActive,
			&i.Menu.ID,
			&i.Menu.RestaurantID,
			&i.Menu.Name,
			&i.Menu.Description,
			&i.Menu.IsActive,
			&i.Menu.SortOrder,
			&i.Menu.AvailableFromMin,
			&i.Menu.AvailableToMin,
			&i.Menu.Days,
			&i.Menu.CreatedAt,
			&i.Menu.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

